#include <bits/stdc++.h>
using namespace std;

#define MOD 998244353

int main() {
	int n;
	int a[501];
	long long dp[501][501][2];

	cin >> n;
	for (int i = 0; i < n; i++)cin >> a[i];
	a[n + 1] = n + 1;

	for (int r = 0; r < n; r++) {
		for (int i = 0; i < 2; i++)dp[r][r][i] = 1LL;
		for (int l = r - 1; l >= 0; l--) {
			for (int i = 0; i < 2; i++)dp[l][r][i] = 0LL;
			for (int k = l; k < r; k++) {
				dp[l][r][0] = (dp[l][r][0] + (dp[l][k][1] * dp[k + 1][r][0])) % MOD;
				if (a[k + 1] < a[r + 1])dp[l][r][1] = (dp[l][r][1] + (dp[l][k][1] * dp[k + 1][r][0])) % MOD;
			}
		}
	}

	cout << dp[0][n - 1][0] << endl;
	return 0;
}
#include <bits/stdc++.h>
using namespace std;

#define MOD 998244353

int main() {
	int n;
	int a[500];
	long long dp[501][501];

	cin >> n;
	for (int i = 0; i < n; i++)cin >> a[i];

	for (int l = n; l >= 1; l--) {
		dp[l][l] = 1;
		for (int r = l + 1; r <= n; r++) {
			dp[l][r] = dp[l + 1][r];
			for (int k = l + 1; k < r; k++) {
				if (a[l] < a[k])dp[l][r] = (dp[l][r] + (dp[l + 1][k] * dp[k][r])) % MOD;
			}
		}
	}

	cout << dp[1][n] << endl;
	return 0;
}
